-- 2. Main: all sections ------------------------------------------------------------------
with r as (

select 1 as section_no, 'OPUS' as project, 'M1' as member,
       'columns' as table_type, 'Hash column types (all tables)' as section_object,
       count(*) as rows_in_scope,
       null::number as null_hkey, null::number as null_fk_hkeys,
       null::number as wrong_length_hkey, null::number as hkey_not_recomputable,
       null::number as collisions, null::number as null_hashdiff,
       count_if(status = 'FAIL') as failing_rows,
       iff(count_if(status = 'FAIL') = 0, 'PASS', 'FAIL') as status,
       'columns checked=' || count(*)
         || iff(count_if(status = 'FAIL') > 0,
                '; non BINARY(16): ' || listagg(iff(status = 'FAIL', table_name || '.' || column_name || ' ' || data_type || coalesce('(' || byte_length || ')', ''), null), ', ') within group (order by table_name, column_name),
                '') as remarks
  from (
        select 'OPUS' as project, table_name, column_name, data_type, character_maximum_length as byte_length,
               iff(data_type = 'BINARY' and character_maximum_length = 16, 'PASS', 'FAIL') as status
          from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS
         where table_schema = 'BGIL_DATA_MODEL'
           and table_name in ('HUB_AGREEMENT', 'HUB_ASSESSMENT', 'HUB_COVERAGE', 'HUB_DISTRIBUTION_CHANNEL', 'HUB_FINANCIAL_ACCOUNT', 'HUB_FINANCIAL_TRANSACTION', 'HUB_LOCATION', 'HUB_ORG_UNIT', 'HUB_PARTY', 'HUB_POLICY', 'HUB_PRODUCT', 'HUB_PROPOSAL', 'HUB_QUOTE', 'HUB_RISK_OBJECT', 'SAT_AUG_COMMON_COMMUNICATION_PREFERENCE', 'SAT_AUG_COVERAGE_DEFINITION', 'SAT_AUG_COVERAGE_LIMITS', 'SAT_AUG_COVERAGE_RATING', 'SAT_AUG_FINTXN_PREMIUM', 'SAT_AUG_LNK_PARTY_ROLE_CORE', 'SAT_AUG_LNK_ROLE_CUSTOMER', 'SAT_AUG_PARTY_BANKING', 'SAT_AUG_PARTY_EMPLOYMENT', 'SAT_AUG_PRODUCT_TERMS', 'SAT_AUG_RISK_PERSON_INSURED', 'SAT_AUG_RISK_PERSON_TRAVEL', 'SAT_COMMON_ADDRESS', 'SAT_COMMON_CLASSIFICATION', 'SAT_COMMON_CONTACT', 'SAT_COVERAGE_CONDITIONS', 'SAT_COVERAGE_DEFINITION', 'SAT_COVERAGE_LIMITS', 'SAT_FINTXN_COMMISSION', 'SAT_FINTXN_HEADER', 'SAT_FINTXN_PREMIUM', 'SAT_FINTXN_TAX', 'SAT_FIN_CHARGE_RATE', 'SAT_FIN_RECEIPT', 'SAT_LNK_ROLE_NOMINEE_BENEFICIARY', 'SAT_ORG_UNIT_DEFINITION', 'SAT_PARTY_EMPLOYMENT', 'SAT_PARTY_HEALTH_PROFILE', 'SAT_PARTY_IDENTIFICATION', 'SAT_PARTY_IDENTITY', 'SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS', 'SAT_POLICY_CLASSIFICATION', 'SAT_POLICY_HEADER', 'SAT_POLICY_TERMS', 'SAT_PRODUCT_DEFINITION', 'SAT_PRODUCT_RATING_FACTOR', 'SAT_PRODUCT_RATING_STRUCTURE', 'SAT_PRODUCT_TERMS', 'SAT_PROPOSAL_UNDERWRITING', 'SAT_QUOTE_HEADER', 'SAT_RISK_MOTOR_DRIVER', 'SAT_RISK_MOTOR_VEHICLE', 'SAT_RISK_OBJECT_CORE', 'SAT_RISK_PERSON_INSURED', 'SAT_RISK_PERSON_TRAVEL')
           and (column_name like '%\\_HKEY' escape '\\' or column_name like 'HASHDIFF%')
  )

union all

select 2 as section_no, 'OPUS' as project, 'M1' as member,
       table_type, 'HUB  HUB_AGREEMENT' as section_object,
       rows_in_scope,
       null_hkey,
       null::number as null_fk_hkeys,
       wrong_length_hkey,
       hkey_not_recomputable,
       collisions,
       null::number as null_hashdiff,
       iff(status = 'FAIL', 1, 0) as failing_rows,
       status,
       nullif(array_to_string(array_construct_compact(
           iff(rows_in_scope = 0, '0 rows in scope', null),
           iff(null_hkey > 0, 'null_hkey=' || null_hkey, null), iff(wrong_length_hkey > 0, 'wrong_length_hkey=' || wrong_length_hkey, null), iff(hkey_not_recomputable > 0, 'hkey_not_recomputable=' || hkey_not_recomputable, null), iff(collisions > 0, 'collisions=' || collisions, null)), '; '), '') as remarks
  from (
        select 'OPUS' as project, 'hub' as table_type, 'HUB_AGREEMENT' as table_name,
               count(*) as rows_in_scope,
               count_if(AGREEMENT_HKEY is null) as null_hkey,
               count_if(AGREEMENT_HKEY is not null and length(AGREEMENT_HKEY) <> 16) as wrong_length_hkey,
               count_if(AGREEMENT_HKEY is not null and PARENT_BK is not null and AGREEMENT_HKEY <> MD5_BINARY(NULLIF(UPPER(TRIM(CAST('OPUS_' || PARENT_BK AS VARCHAR))), ''))) as hkey_not_recomputable,
               (select count(*) from (
            select AGREEMENT_HKEY as hkey, count(distinct PARENT_BK) as bks
              from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_AGREEMENT where RECORD_SOURCE in ('OPUS_BA_TRV_DATA_POLICY_DTLS', 'OPUS_BA_TRV_PLAN_MST', 'OPUS_BJAZ_TRV_DETLS_EXTN', 'OPUS_BJAZ_TRV_LOADER_LOG_TABLE', 'OPUS_BJAZ_TRV_RATE_MASTER') group by AGREEMENT_HKEY having count(distinct PARENT_BK) > 1
               )) as collisions,
               iff(null_hkey = 0 and wrong_length_hkey = 0 and coalesce(hkey_not_recomputable, 0) = 0 and collisions = 0, 'PASS', 'FAIL') as status
          from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_AGREEMENT
         where RECORD_SOURCE in ('OPUS_BA_TRV_DATA_POLICY_DTLS', 'OPUS_BA_TRV_PLAN_MST', 'OPUS_BJAZ_TRV_DETLS_EXTN', 'OPUS_BJAZ_TRV_LOADER_LOG_TABLE', 'OPUS_BJAZ_TRV_RATE_MASTER')
  )

union all

select 3 as section_no, 'OPUS' as project, 'M1' as member,
       table_type, 'HUB  HUB_ASSESSMENT' as section_object,
       rows_in_scope,
       null_hkey,
       null::number as null_fk_hkeys,
       wrong_length_hkey,
       hkey_not_recomputable,
       collisions,
       null::number as null_hashdiff,
       iff(status = 'FAIL', 1, 0) as failing_rows,
       status,
       nullif(array_to_string(array_construct_compact(
           iff(rows_in_scope = 0, '0 rows in scope', null),
           iff(null_hkey > 0, 'null_hkey=' || null_hkey, null), iff(wrong_length_hkey > 0, 'wrong_length_hkey=' || wrong_length_hkey, null), iff(hkey_not_recomputable > 0, 'hkey_not_recomputable=' || hkey_not_recomputable, null), iff(collisions > 0, 'collisions=' || collisions, null)), '; '), '') as remarks
  from (
        select 'OPUS' as project, 'hub' as table_type, 'HUB_ASSESSMENT' as table_name,
               count(*) as rows_in_scope,
               count_if(ASSESSMENT_HKEY is null) as null_hkey,
               count_if(ASSESSMENT_HKEY is not null and length(ASSESSMENT_HKEY) <> 16) as wrong_length_hkey,
               count_if(ASSESSMENT_HKEY is not null and PARENT_BK is not null and ASSESSMENT_HKEY <> MD5_BINARY(NULLIF(UPPER(TRIM(CAST('OPUS_' || PARENT_BK AS VARCHAR))), ''))) as hkey_not_recomputable,
               (select count(*) from (
            select ASSESSMENT_HKEY as hkey, count(distinct PARENT_BK) as bks
              from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_ASSESSMENT where RECORD_SOURCE in ('OPUS_BA_TRV_DATA_POLICY_DTLS', 'OPUS_BJAZ_TRV_LOADER_DATA') group by ASSESSMENT_HKEY having count(distinct PARENT_BK) > 1
               )) as collisions,
               iff(null_hkey = 0 and wrong_length_hkey = 0 and coalesce(hkey_not_recomputable, 0) = 0 and collisions = 0, 'PASS', 'FAIL') as status
          from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_ASSESSMENT
         where RECORD_SOURCE in ('OPUS_BA_TRV_DATA_POLICY_DTLS', 'OPUS_BJAZ_TRV_LOADER_DATA')
  )

union all

select 4 as section_no, 'OPUS' as project, 'M1' as member,
       table_type, 'HUB  HUB_COVERAGE' as section_object,
       rows_in_scope,
       null_hkey,
       null::number as null_fk_hkeys,
       wrong_length_hkey,
       hkey_not_recomputable,
       collisions,
       null::number as null_hashdiff,
       iff(status = 'FAIL', 1, 0) as failing_rows,
       status,
       nullif(array_to_string(array_construct_compact(
           iff(rows_in_scope = 0, '0 rows in scope', null),
           iff(null_hkey > 0, 'null_hkey=' || null_hkey, null), iff(wrong_length_hkey > 0, 'wrong_length_hkey=' || wrong_length_hkey, null), iff(hkey_not_recomputable > 0, 'hkey_not_recomputable=' || hkey_not_recomputable, null), iff(collisions > 0, 'collisions=' || collisions, null)), '; '), '') as remarks
  from (
        select 'OPUS' as project, 'hub' as table_type, 'HUB_COVERAGE' as table_name,
               count(*) as rows_in_scope,
               count_if(COVERAGE_HKEY is null) as null_hkey,
               count_if(COVERAGE_HKEY is not null and length(COVERAGE_HKEY) <> 16) as wrong_length_hkey,
               count_if(COVERAGE_HKEY is not null and PARENT_BK is not null and COVERAGE_HKEY <> MD5_BINARY(NULLIF(UPPER(TRIM(CAST('OPUS_' || PARENT_BK AS VARCHAR))), ''))) as hkey_not_recomputable,
               (select count(*) from (
            select COVERAGE_HKEY as hkey, count(distinct PARENT_BK) as bks
              from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_COVERAGE where RECORD_SOURCE in ('OPUS_BJAZ_TRV_LOADER_DATA', 'OPUS_BJAZ_TRV_PLAN', 'OPUS_BJAZ_TRV_RIDER_DTLS', 'OPUS_BJAZ_TRV_RIDER_RATE_MAST') group by COVERAGE_HKEY having count(distinct PARENT_BK) > 1
               )) as collisions,
               iff(null_hkey = 0 and wrong_length_hkey = 0 and coalesce(hkey_not_recomputable, 0) = 0 and collisions = 0, 'PASS', 'FAIL') as status
          from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_COVERAGE
         where RECORD_SOURCE in ('OPUS_BJAZ_TRV_LOADER_DATA', 'OPUS_BJAZ_TRV_PLAN', 'OPUS_BJAZ_TRV_RIDER_DTLS', 'OPUS_BJAZ_TRV_RIDER_RATE_MAST')
